if(!PKR.packs.some(p=>p.id==='ancient')){const ld=(u,f)=>{const sc=document.createElement('script');sc.src=u;sc.onload=()=>{Object.assign(PACKS,shopMeta());try{PKR.fillNames(PI);PKR.picList().forEach((c,i)=>{if(c)PIC[25+i]=c})}catch(e){console.warn(e)}try{redo()}catch(e){}};sc.onerror=f;document.head.appendChild(sc)};ld('packs/ancient.js?v=7',()=>ld('ancient.js?v=7',()=>console.warn('Ancient pack file not found')))}
const curPack=()=>PACKS[localStorage.dhPack]?localStorage.dhPack:'desert',COST=()=>PACKS[curPack()].cost;
const packOf=c=>c.pack||PKR.packOf(c.slot,c.idx)||'desert';
const packCards=pk=>(DH.cards||[]).filter(c=>packOf(c)==(pk||curPack()));
Object.assign(I,{merge:pp('M3 4h7l4 8-4 8H3l4-8z',O)+pp('M21 4h-7l4 8-4 8h7l-4-8z',G,'opacity=".85"'),coin:cc(12,12,10,'#b97a08')+cc(12,12,8.6,'#ffd23a')+cc(12,12,6.4,'none','stroke="#b97a08" stroke-width="1.2"')+pp('M12 7.2l1.5 3.2 3.5.4-2.6 2.4.7 3.5L12 14.900l-3.100 1.800.7-3.500L7 10.800l3.500-.4z','#b97a08')+pp('M7 5.500Q10 3.500 14 4','rgba(255,255,255,.7)'),
 cards:pp('M6 5h8a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2z',G,'transform="rotate(-10 10 12)"')+pp('M10 4h8a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-8a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z',O,'transform="rotate(8 14 11)"')+pp('M14 8.500l1 2.100 2.300.3-1.700 1.600.4 2.300-2-1.100-2 1.100.4-2.300-1.700-1.600 2.300-.3z',W)});
const rpc=async(n,a)=>{const {data,error}=await sb.rpc(n,a||{});if(error){const m=error.message||'Something went wrong';if(/function .* does not exist|schema cache|relation .* does not exist/i.test(m))DH.bad=true;throw new Error(m)}return data};
const refLink=()=>location.origin+location.pathname+'?ref='+encodeURIComponent((window.mp&&mp.username)||(typeof mp!='undefined'&&mp&&mp.username)||'');
const num=n=>{n=Math.round(n*10)/10;return Number.isInteger(n)?String(n):n.toFixed(1)};
