const packBlurb=k=>{const cs=packCards(k);if(!cs.length)return `<p class="mu">${esc(PACKS[k].tag||'')}</p>`;const sl=['f','b','e','m','x'].filter(s=>cs.some(c=>c.slot==s)),mx=Math.max(...cs.map(c=>RO.indexOf(c.rarity))),top=cs.filter(c=>RO.indexOf(c.rarity)==mx),R=RAR[RO[mx]];
return `<div class="dhbl"><div class="ln"><b>3 Cards</b><span class="mu">·</span>${sl.map(s=>`<span class="sl" title="${SLOT[s]}">${sI(s)}</span>`).join('')}</div><div class="ln"><span class="mu">Top Pull · ${R.n}</span>${top.map(c=>`<span class="tp" style="--rc:${R.c}">${sI(c.slot,14)} ${esc(c.name)}</span>`).join('')}</div></div>`};
