/* ---------- SHOP ---------- */
function tkSection(){return Object.keys(window.SPK||{}).filter(k=>DH.tk[k]>0).map(k=>{const p=SPK[k];return `<div class="card dhshop dhtkc ${k}" style="--tc:${p.c}"><div class="dhstage"><div class="dhaura"></div>${packH({cls:'idle',pack:k})}</div><div class="dhinfo"><div class="dhtt"><h3>${p.n}</h3></div><p class="mu" style="margin:2px 0 8px">${p.tag}</p><div class="row wrap" style="gap:10px"><span class="dhtkn">${ic('merge',16)} <b>${DH.tk[k]}</b> ${p.ticket}${DH.tk[k]>1?'s':''}</span></div><button type="button" class="btn dhgo" data-act="dhtk" data-id="${k}">Open with ticket</button></div></div>`}).join('')}
function shopPg(){const st=DH.st,left_=DAILY_CAP-st.opened_today,one=localStorage.dhOne=='1';
 A.innerHTML=shell('',`${tkSection()}<div class="row wrap dhpks" style="gap:8px;margin:0 0 10px">${Object.entries(PACKS).map(([k,p])=>`<button type="button" class="chip ${k==curPack()?'sel':''}" data-act="dhpk" data-id="${k}"><span class="pki">${PKR.packArt(k)}</span>${p.n} · ${tok(p.cost,14)}</button>`).join('')}</div><div class="card dhshop"><div class="dhstage"><div class="dhaura"></div>${packH({cls:'idle'})}</div><div class="dhinfo"><div class="dhtt"><h3>${PACKS[curPack()].n}</h3><button type="button" class="dhi" data-act="dhodds" aria-label="Drop odds">i</button></div>${packBlurb(curPack())}<div class="row wrap" style="gap:10px"><span class="mu">Cost</span>${tok(COST(),20)}<span class="mu">·</span><span class="mu">${left_} of ${DAILY_CAP} packs left today</span></div><button type="button" class="btn dhgo" data-act="dhopen" ${left_<1||st.balance<COST()?'disabled':''}>${left_<1?'Daily limit reached':st.balance<COST()?'Need '+COST()+' tokens':'Open pack'}</button>${st.balance<COST()&&left_>0?`<a class="chip" href="#/deck/rewards">${ic('star',16)} Earn tokens</a>`:''}</div></div>
 <h4 class="sg">Your ${PACKS[curPack()].n.replace(' Pack','')} collection</h4>${collGrid()}
 <p class="dhfine"><button type="button" class="dhcog" data-act="dhcog" aria-label="Pack settings">${ic('gear',14)}</button></p>`);
 pkTilt()}
function collGrid(){const cs=packCards().sort((a,b)=>RO.indexOf(a.rarity)-RO.indexOf(b.rarity)),have=cs.filter(c=>DH.inv[c.id]&&DH.inv[c.id].qty>0).length;return `<div class="mu" style="margin:0 0 8px">${have} / ${cs.length} collected</div><div class="dcg">${cs.map(c=>DH.inv[c.id]&&DH.inv[c.id].qty>0?cardH(c,{qty:DH.inv[c.id].qty,attr:`data-act="dhcard" data-id="${c.id}"`}):ghostH(c)).join('')}</div>`}
function pkTilt(){document.querySelectorAll('[data-pk]').forEach(p=>{if(p._t)return;p._t=1;const mv=e=>{const r=p.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;p.style.setProperty('--ry',((x-.5)*26)+'deg');p.style.setProperty('--rx',((.5-y)*20)+'deg');p.style.setProperty('--px',(x*100)+'%');p.style.setProperty('--py',(y*100)+'%')};p.addEventListener('pointermove',mv);p.addEventListener('pointerleave',()=>{p.style.setProperty('--ry','0deg');p.style.setProperty('--rx','0deg')})})}

/* ---------- PACK OPENING ---------- */
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
/* Server (dh_open_pack, SECURITY DEFINER) already wrote the cards; mirror its result locally at once so they show everywhere immediately. Server data is re-synced by loadInv() right after. */
function applyPull(r){if(!r||!Array.isArray(r.cards))return;DH.inv=DH.inv||{};r.cards.forEach(id=>{const c=DH.cmap&&DH.cmap[id];if(!c)return;const x=DH.inv[id]||(DH.inv[id]={card:id,qty:0,locked:0});x.qty=(x.qty|0)+1;PKR.inv.add(c.slot+c.idx)});if(r.status)DH.st=r.status}
